files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  color: var(--accent);
  letter-spacing: 1px;
}

.display {
  font-size: clamp(3rem, 18vw, 5rem);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 2px;
  margin-bottom: 8px;
  color: var(--text);
}

.message {
  min-height: 1.5em;
  font-size: 1.25rem;
  color: var(--accent);
  margin-bottom: 16px;
  font-weight: 600;
}

.inputs {
  display: flex;
  gap: 8px;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 24px;
}

.inputs label {
  font-size: 0.9rem;
  color: var(--muted);
}

.inputs input {
  width: 70px;
  padding: 8px;
  font-size: 1rem;
  border: 2px solid var(--muted);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  text-align: center;
}

.inputs input:focus {
  outline: none;
  border-color: var(--accent);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  background: var(--muted);
  color: var(--bg);
  transition: background 0.2s, transform 0.1s;
}

button:hover:not(:disabled) {
  background: var(--accent);
  color: #fff;
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active:not(:disabled) {
  transform: scale(0.96);
}

button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  button {
    padding: 10px 18px;
    font-size: 0.95rem;
  }
}

const display = document.getElementById('display');
const message = document.getElementById('message');
const minutesInput = document.getElementById('minutes');
const secondsInput = document.getElementById('seconds');
const startBtn = document.getElementById('startBtn');
const pauseBtn = document.getElementById('pauseBtn');
const resetBtn = document.getElementById('resetBtn');

let totalSeconds = 0;
let remaining = 0;
let timerId = null;
let running = false;

function formatTime(sec) {
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}

function updateDisplay() {
  display.textContent = formatTime(remaining);
}

function stopTimer() {
  if (timerId !== null) {
    clearInterval(timerId);
    timerId = null;
  }
  running = false;
  pauseBtn.disabled = true;
  startBtn.disabled = false;
}

function tick() {
  if (remaining <= 0) {
    stopTimer();
    message.textContent = "Time's up!";
    return;
  }
  remaining--;
  updateDisplay();
  if (remaining === 0) {
    stopTimer();
    message.textContent = "Time's up!";
  }
}

function start() {
  if (running) return;
  if (remaining === 0) {
    const m = parseInt(minutesInput.value, 10) || 0;
    const s = parseInt(secondsInput.value, 10) || 0;
    if (s >= 60) {
      message.textContent = 'Seconds must be 0-59';
      return;
    }
    totalSeconds = m * 60 + s;
    if (totalSeconds <= 0) {
      message.textContent = 'Enter a time greater than 0';
      return;
    }
    remaining = totalSeconds;
    updateDisplay();
  }
  message.textContent = '';
  running = true;
  startBtn.disabled = true;
  pauseBtn.disabled = false;
  timerId = setInterval(tick, 1000);
}

function pause() {
  if (!running) return;
  stopTimer();
}

function reset() {
  stopTimer();
  remaining = 0;
  totalSeconds = 0;
  message.textContent = '';
  updateDisplay();
  minutesInput.value = 0;
  secondsInput.value = 0;
}

startBtn.addEventListener('click', start);
pauseBtn.addEventListener('click', pause);
resetBtn.addEventListener('click', reset);

updateDisplay();
